<native platform="ios">
import AuthenticationServices

/// Opens the authorization URL in ASWebAuthenticationSession and answers with
/// the redirect URL. Errors are "CODE: message" so JS can normalize them.
final class SocialLoginAuthSessionModule: NSObject, NativeModule, ASWebAuthenticationPresentationContextProviding {
    var moduleName: String { "SocialLoginAuthSession" }
    private var session: ASWebAuthenticationSession?

    func invoke(method: String, args: [Any], callback: @escaping (Any?, String?) -> Void) {
        switch method {
        case "open":
            guard let urlString = args.first as? String, let url = URL(string: urlString),
                  args.count > 1, let redirectString = args[1] as? String,
                  let redirect = URL(string: redirectString), let scheme = redirect.scheme else {
                callback(nil, "INVALID_CONFIG: open(url, redirectUri, ephemeral) needs two valid URLs")
                return
            }
            let ephemeral = (args.count > 2 ? args[2] as? Bool : nil) ?? false
            DispatchQueue.main.async {
                self.open(url: url, redirect: redirect, scheme: scheme, ephemeral: ephemeral, callback: callback)
            }
        case "isAvailable":
            callback(true, nil)
        case "cancel":
            DispatchQueue.main.async {
                self.session?.cancel()
                self.session = nil
                callback(nil, nil)
            }
        default:
            callback(nil, "NOT_SUPPORTED: unknown method \(method)")
        }
    }

    private func open(url: URL, redirect: URL, scheme: String, ephemeral: Bool, callback: @escaping (Any?, String?) -> Void) {
        if session != nil {
            callback(nil, "INVALID_CONFIG: Another sign-in is already in progress")
            return
        }
        let completion: (URL?, Error?) -> Void = { [weak self] callbackURL, error in
            self?.session = nil
            if let callbackURL {
                callback(callbackURL.absoluteString, nil)
                return
            }
            let nsError = error as NSError?
            if nsError?.domain == ASWebAuthenticationSessionError.errorDomain,
               nsError?.code == ASWebAuthenticationSessionError.canceledLogin.rawValue {
                callback(nil, "CANCELLED: The user closed the browser")
            } else {
                callback(nil, "NOT_SUPPORTED: \(error?.localizedDescription ?? "unknown error")")
            }
        }
        let next: ASWebAuthenticationSession
        if scheme.lowercased() == "https" {
            // Universal Link callbacks need iOS 17.4 (ASWebAuthenticationSession.Callback).
            guard #available(iOS 17.4, *), let host = redirect.host else {
                callback(nil, "NOT_SUPPORTED: https redirects need iOS 17.4; use your app's scheme (callbackUri) instead")
                return
            }
            next = ASWebAuthenticationSession(url: url, callback: .https(host: host, path: redirect.path), completionHandler: completion)
        } else {
            next = ASWebAuthenticationSession(url: url, callbackURLScheme: scheme, completionHandler: completion)
        }
        next.prefersEphemeralWebBrowserSession = ephemeral
        next.presentationContextProvider = self
        session = next
        if !next.start() {
            session = nil
            callback(nil, "NOT_SUPPORTED: ASWebAuthenticationSession could not start")
        }
    }

    func presentationAnchor(for session: ASWebAuthenticationSession) -> ASPresentationAnchor {
        UIApplication.shared.vn_keyWindow ?? ASPresentationAnchor()
    }

    func destroy() {
        session?.cancel()
        session = nil
    }
}
