<native platform="android">
import android.app.Activity
import android.content.ActivityNotFoundException
import android.content.Intent
import android.net.Uri
import android.os.Bundle

/**
 * Opens the authorization URL in a Custom Tab (plain ACTION_VIEW intent with
 * the Custom Tabs extras, so no androidx.browser dependency) and answers with
 * the redirect URL. Errors are "CODE: message" so JS can normalize them.
 */
class SocialLoginAuthSessionModule : NativeModule {
    override val moduleName: String = "SocialLoginAuthSession"
    private var context: Context? = null

    override fun initialize(context: Context, bridge: NativeBridge) {
        this.context = context
    }

    override fun invoke(method: String, args: List<Any?>, bridge: NativeBridge, callback: (Any?, String?) -> Unit) {
        when (method) {
            "open" -> {
                val url = args.getOrNull(0) as? String
                val redirect = (args.getOrNull(1) as? String)?.let(Uri::parse)
                val host = context
                if (url == null || redirect?.scheme == null || host == null) {
                    callback(null, "INVALID_CONFIG: open(url, redirectUri, ephemeral) needs two valid URLs")
                    return
                }
                // Without an intent-filter for the scheme the browser would
                // never come back: fail now instead.
                val probe = Intent(Intent.ACTION_VIEW, redirect)
                    .addCategory(Intent.CATEGORY_BROWSABLE)
                    .setPackage(host.packageName)
                if (!redirect.scheme.equals("https", ignoreCase = true) &&
                    host.packageManager.queryIntentActivities(probe, 0).isEmpty()
                ) {
                    callback(null, "INVALID_CONFIG: No activity handles ${redirect.scheme}:// redirects. Run `npx vue-native-social-login setup --scheme ${redirect.scheme}` and rebuild the app.")
                    return
                }
                val began = SocialLoginAuthSession.begin(redirect, object : SocialLoginAuthSession.Listener {
                    override fun onRedirect(url: String) = callback(url, null)
                    override fun onError(code: String, message: String) = callback(null, "$code: $message")
                })
                if (!began) {
                    callback(null, "INVALID_CONFIG: Another sign-in is already in progress")
                    return
                }
                val intent = SocialLoginAuthSessionActivity.startIntent(host, url)
                if (host !is Activity) intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                host.startActivity(intent)
            }
            "isAvailable" -> callback(true, null)
            "cancel" -> {
                context?.let { host ->
                    if (SocialLoginAuthSession.isActive) {
                        val intent = SocialLoginAuthSessionActivity.cancelIntent(host)
                        if (host !is Activity) intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                        host.startActivity(intent)
                    }
                }
                callback(null, null)
            }
            else -> callback(null, "NOT_SUPPORTED: unknown method $method")
        }
    }

    override fun destroy() {
        SocialLoginAuthSession.fail("CANCELLED", "The app closed", notify = false)
        context = null
    }
}

/** The single sign-in in progress; the activities report its outcome here. */
object SocialLoginAuthSession {
    interface Listener {
        fun onRedirect(url: String)
        fun onError(code: String, message: String)
    }

    private var listener: Listener? = null
    private var redirectUri: Uri? = null

    @Synchronized
    fun begin(redirectUri: Uri, listener: Listener): Boolean {
        if (this.listener != null) return false
        this.listener = listener
        this.redirectUri = redirectUri
        return true
    }

    val isActive: Boolean
        @Synchronized get() = listener != null

    /** Whether [uri] is the redirect of the sign-in in progress (scheme, host, port, path). */
    @Synchronized
    fun matchesRedirect(uri: Uri?): Boolean {
        val expected = redirectUri ?: return false
        if (uri == null) return false
        return expected.scheme.equals(uri.scheme, ignoreCase = true) &&
            (expected.host ?: "").equals(uri.host ?: "", ignoreCase = true) &&
            expected.port == uri.port &&
            (expected.path ?: "").trimEnd('/') == (uri.path ?: "").trimEnd('/')
    }

    fun completeWithRedirect(url: String) {
        take()?.onRedirect(url)
    }

    fun fail(code: String, message: String, notify: Boolean = true) {
        val current = take()
        if (notify) current?.onError(code, message)
    }

    @Synchronized
    private fun take(): Listener? {
        val current = listener
        listener = null
        redirectUri = null
        return current
    }
}

/**
 * Sits between the app and the browser tab. First resume: opens the URL.
 * Next resume: either SocialLoginRedirectActivity delivered the redirect, or
 * the user closed the tab (cancelled).
 */
class SocialLoginAuthSessionActivity : Activity() {
    private var browserOpened = false

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        browserOpened = savedInstanceState?.getBoolean(STATE_BROWSER_OPENED) ?: false
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
    }

    override fun onSaveInstanceState(outState: Bundle) {
        super.onSaveInstanceState(outState)
        outState.putBoolean(STATE_BROWSER_OPENED, browserOpened)
    }

    override fun onResume() {
        super.onResume()
        if (intent.getBooleanExtra(EXTRA_CANCEL, false)) {
            SocialLoginAuthSession.fail("CANCELLED", "The sign-in was cancelled")
            finish()
            return
        }
        if (!browserOpened) {
            browserOpened = true
            openBrowser()
            return
        }
        val redirect = intent.data
        if (redirect != null) {
            SocialLoginAuthSession.completeWithRedirect(redirect.toString())
        } else {
            SocialLoginAuthSession.fail("CANCELLED", "The user closed the browser")
        }
        finish()
    }

    private fun openBrowser() {
        val url = intent.getStringExtra(EXTRA_AUTH_URL)
        if (url == null || !SocialLoginAuthSession.isActive) {
            SocialLoginAuthSession.fail("CANCELLED", "The sign-in was interrupted")
            finish()
            return
        }
        // The Custom Tabs protocol is two intent extras: a (null) session
        // binder and the title flag. Browsers without Custom Tabs ignore them.
        val extras = Bundle().apply { putBinder(EXTRA_CUSTOM_TABS_SESSION, null) }
        val browser = Intent(Intent.ACTION_VIEW, Uri.parse(url))
            .addCategory(Intent.CATEGORY_BROWSABLE)
            .putExtras(extras)
            .putExtra(EXTRA_CUSTOM_TABS_TITLE, 1)
        try {
            startActivity(browser)
        } catch (e: ActivityNotFoundException) {
            SocialLoginAuthSession.fail("NOT_SUPPORTED", "No browser is available to sign in")
            finish()
        }
    }

    companion object {
        private const val EXTRA_AUTH_URL = "socialLogin.AUTH_URL"
        private const val EXTRA_CANCEL = "socialLogin.CANCEL"
        private const val STATE_BROWSER_OPENED = "browserOpened"
        private const val EXTRA_CUSTOM_TABS_SESSION = "android.support.customtabs.extra.SESSION"
        private const val EXTRA_CUSTOM_TABS_TITLE = "android.support.customtabs.extra.TITLE_VISIBILITY"

        fun startIntent(context: Context, url: String): Intent =
            Intent(context, SocialLoginAuthSessionActivity::class.java).putExtra(EXTRA_AUTH_URL, url)

        fun redirectIntent(context: Context, redirect: Uri?): Intent =
            Intent(context, SocialLoginAuthSessionActivity::class.java)
                .setData(redirect)
                .addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP)

        fun cancelIntent(context: Context): Intent =
            Intent(context, SocialLoginAuthSessionActivity::class.java)
                .putExtra(EXTRA_CANCEL, true)
                .addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP)
    }
}

/** Entry point for the provider's redirect: forwards it only when it belongs to the sign-in in progress. */
class SocialLoginRedirectActivity : Activity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        if (SocialLoginAuthSession.matchesRedirect(intent.data)) {
            startActivity(SocialLoginAuthSessionActivity.redirectIntent(this, intent.data))
        }
        finish()
    }
}
